bool nawiasy_ok(string s) {
    char stos[1000];
    int top = -1;
    for (int i = 0; i < s.length(); i++) {
        if (s[i] == '(' || s[i] == '[' || s[i] == '{') {
            stos[++top] = s[i];
        } else if (s[i] == ')' || s[i] == ']' || s[i] == '}') {
            if (top < 0) return false;
            char otw = stos[top--];
            if (s[i] == ')' && otw != '(') return false;
            if (s[i] == ']' && otw != '[') return false;
            if (s[i] == '}' && otw != '{') return false;
        }
    }
    return top == -1;
}
```

